$org="NnamdiDev"
$objects = @("EmbeddedServiceConfig","EmbeddedServiceBranding","EmbeddedServiceLayout","EmbeddedServiceCustomComponent","EmbeddedServiceFlow","EmbeddedServiceFlowConfig","EinsteinAgentSettings","ServiceAISetupDefinition","AIApplication","AIApplicationConfig","Prompt","PromptVersion")
function Invoke-Query([string]$soql) { $out = & sf data query --target-org $org --use-tooling-api --query $soql --json 2>$null | Out-String; if ($LASTEXITCODE -ne 0) { return $null }; return $out | ConvertFrom-Json }
foreach ($obj in $objects) { $queries = @("SELECT Id, DeveloperName FROM $obj LIMIT 20","SELECT Id, Name FROM $obj LIMIT 20","SELECT Id, MasterLabel FROM $obj LIMIT 20","SELECT Id FROM $obj LIMIT 20"); $res = $null; foreach ($q in $queries) { $res = Invoke-Query $q; if ($res) { break } }; if (-not $res) { Write-Output "$obj: query failed/unsupported"; continue }; $recs = @($res.result.records); if ($recs.Count -eq 0) { Write-Output "$obj: 0 records"; continue }; $items = $recs | ForEach-Object { if ($_.DeveloperName) { "$($_.DeveloperName) [$($_.Id)]" } elseif ($_.Name) { "$($_.Name) [$($_.Id)]" } elseif ($_.MasterLabel) { "$($_.MasterLabel) [$($_.Id)]" } else { $_.Id } }; Write-Output ("$obj: $($res.result.totalSize) records -> " + ($items -join "; ")) }
